import React, { useMemo, Children, isValidElement, cloneElement } from "react";
import { useTheme } from "@theme";

import { AreaProps, AreaChartProps } from "../chart.types";

type UseAreaChartParams = Pick<AreaChartProps, "data" | "children" | "type">;

export const useAreaChart = ({ data: initialData, children, type }: UseAreaChartParams) => {
  const theme = useTheme();

  const derived = useMemo(() => {
    if (!theme) {
      return {
        numCategoricalColors: 0,
        numAreas: 0,
        childrenWithProps: children,
        gradientDefs: [] as React.ReactElement[],
        colorMap: {} as Record<string, string>,
      };
    }

    const categoricalColorKeys = Object.keys(theme.color.data.categorical).filter((key) =>
      key.endsWith("Default"),
    );
    const numCategoricalColors = categoricalColorKeys.length;

    const numAreas = Children.toArray(children).reduce((acc: number, child) => {
      if (
        isValidElement(child) &&
        (child.type as { displayName?: string })?.displayName === "Area"
      ) {
        return acc + 1;
      }
      return acc;
    }, 0);

    let areaIndexCount = 0;
    const gradientDefs: React.ReactElement[] = [];
    const colorMap: Record<string, string> = {};

    const childrenWithProps = Children.map(children, (child) => {
      if (
        isValidElement(child) &&
        (child.type as { displayName?: string })?.displayName === "Area"
      ) {
        const currentAreaIndex = areaIndexCount++;
        const {
          dataKey,
          name,
          forecastDataIndex,
          forecastOpacity = 0.4,
          variant,
        } = child.props as AreaProps;

        const areaProps: AreaProps = {
          areaIndex: currentAreaIndex,
          ...child.props,
          // Default legendType to "square" so Recharts auto-generates square-type legend entries.
          // Recharts Area defaults to "line", which would render a line icon in the legend.
          // User can override by explicitly passing legendType on the <Area> component.
          legendType: child.props.legendType ?? "square",
        };

        // Resolved color for this area index (consistent with Area component logic)
        const colorKey = `${
          (currentAreaIndex % numCategoricalColors) + 1
        }Default` as keyof typeof theme.color.data.categorical;
        const resolvedColor = theme.color.data.categorical[colorKey];

        // Map both dataKey and name to the resolved color for Legend lookup
        if (dataKey) colorMap[String(dataKey)] = resolvedColor;
        if (name) colorMap[String(name)] = resolvedColor;

        // Dashed areas are typically overlays (e.g. thresholds, targets) and shouldn't be stacked
        if (type === "stacked" && variant !== "dashed") {
          areaProps.stackId = child.props.stackId || "1";
        }

        if (forecastDataIndex !== undefined && initialData && initialData.length > 0) {
          const offset = (forecastDataIndex / Math.max(1, initialData.length - 1)) * 100 + "%";
          const gradientId = `textura-area-gradient-${dataKey}`;

          gradientDefs.push(
            React.createElement(
              "linearGradient",
              {
                id: gradientId,
                key: gradientId,
                x1: "0",
                y1: "0",
                x2: "1",
                y2: "0",
              },
              React.createElement("stop", { offset, stopColor: resolvedColor, stopOpacity: 1 }),
              React.createElement("stop", {
                offset,
                stopColor: resolvedColor,
                stopOpacity: forecastOpacity,
              }),
            ),
          );

          areaProps.fill = `url(#${gradientId})`;
        }

        return cloneElement(child as React.ReactElement<AreaProps>, areaProps);
      }
      return child;
    });

    return {
      numCategoricalColors,
      numAreas,
      childrenWithProps,
      gradientDefs,
      colorMap,
    };
  }, [theme, children, type, initialData]);

  return {
    chartData: initialData,
    ...derived,
  };
};
